static std::string bytes(const std::filesystem::path &p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
static void write(const std::filesystem::path &p,const std::vector<unsigned char> &b){std::ofstream f(p,std::ios::binary);f.write((char *)b.data(),b.size());}
static studio::ImportMedia sheet(){studio::ImportMedia m;m.w=16;m.h=8;m.delays_ms={0};m.rgba.assign(16*8*4,255);for(int i=0;i<2;++i)for(int y=2;y<6;++y)for(int x=2;x<6;++x){auto p=m.rgba.data()+(y*16+x+i*8)*4;p[0]=i?0:255;p[1]=0;p[2]=i?255:0;}auto p=m.rgba.data()+(3*16+3)*4;p[0]=p[1]=p[2]=0;return m;}
// Clear before every literal keeps the handcrafted LZW stream at three bits per code.
static std::vector<unsigned char> gif(){std::vector<unsigned char> b={'G','I','F','8','9','a',2,0,2,0,0x81,0,0,0,0,0,255,0,0,0,0,255,255,255,255};for(int frame=0;frame<2;++frame){int delay=frame?600:4;b.insert(b.end(),{0x21,0xf9,4,0,(unsigned char)delay,(unsigned char)(delay>>8),0,0,0x2c,0,0,0,0,2,0,2,0,0,2});std::vector<unsigned char> data;unsigned acc=0;int bits=0;auto code=[&](int c){acc|=c<<bits;bits+=3;while(bits>=8){data.push_back((unsigned char)acc);acc>>=8;bits-=8;}};for(int i=0;i<4;++i){code(4);code(frame?2:1);}code(5);if(bits)data.push_back((unsigned char)acc);b.push_back((unsigned char)data.size());b.insert(b.end(),data.begin(),data.end());b.push_back(0);}b.push_back(0x3b);return b;}
