    auto png=root/fs::u8path(u8"雪.png");std::vector<unsigned char> encoded;auto sink=[](void *context,void *data,int n){auto &out=*(std::vector<unsigned char> *)context;out.insert(out.end(),(unsigned char *)data,(unsigned char *)data+n);};CHECK(stbi_write_png_to_func(sink,&encoded,m.w,m.h,4,m.rgba.data(),m.w*4));write(png,encoded);ImportMedia decoded;CHECK(decode_import_media(png.u8string(),decoded,error)&&decoded.rgba==m.rgba);auto gif_path=root/fs::u8path(u8"动画.gif");auto gb=gif();write(gif_path,gb);CHECK(decode_import_media(gif_path.u8string(),decoded,error)&&decoded.kind==MediaKind::Gif&&decoded.delays_ms==std::vector<int>({40,6000}));o={};o.trim=false;o.prefix="GIF";CHECK(build_import_batch(*art,decoded,o,batch,error)&&batch.frames.size()==2&&batch.frames[1].ticks>255);CHECK(batch.frames[0].ticks==(int)std::lround(.04*mk2_tick_hz));int duration=batch.frames[0].ticks+batch.frames[1].ticks;CHECK(art->import_batch(batch,error)==original_count);CHECK(read_embedded(*art,records,error)&&embedded_duration(records[0])==duration&&records[0].entries.size()==3&&records[0].entries[1].values.index==original_count+1&&records[0].entries[2].values.index==original_count+1);CHECK(art->save(baseline.u8string(),error));loaded=Artwork::open(baseline.u8string(),error);CHECK(loaded&&read_embedded(*loaded,records,error)&&embedded_duration(records[0])==duration);art->undo();CHECK(art->save(baseline.u8string(),error)&&bytes(baseline)==original);
    // Shared GIF crop keeps different poses registered, including transparent black.
